INSERT INTO posts (id, public_id, author_id, primary_term_id, post_type, title, slug, excerpt, body, body_format, cover_image_url, cover_image_alt, reading_time_minutes, status, visibility, published_at, scheduled_for, is_featured, is_pinned, related_location_id, related_category_id, seo_title, seo_description, is_indexable, created_by_user_id, created_at) VALUES
(1, '01K2F2DKG0CXCEZPNKE2VT49X4', 2, 2, 'market_report', 'Where the World''s Wealthy Are Buying in 2026', 'where-the-world-s-wealthy-are-buying-in-2026-1', 'Where the World''s Wealthy Are Buying in 2026: what the transaction data actually shows, and what it means if you are buying in the next twelve months.', '<p>Where the World''s Wealthy Are Buying in 2026 is a question that comes up in almost every conversation we have with buyers at the top of the market, and the honest answer has changed considerably over the last eighteen months.</p>  <p>What follows is not a forecast. It is what the transaction data actually shows, set against what agents on the ground are telling us about enquiry volumes, time to offer, and the gap between asking and achieved prices.</p>  <h2>Where the money is going</h2>  <p>The pattern is consistent across the markets we track: scarcity of genuinely prime stock is doing more to support values than demand growth is. Where new supply has arrived at the top end, it has been absorbed quickly, but the volume is small relative to the depth of the buyer pool.</p>  <h2>What this means for buyers</h2>  <p>Be ready to move. The best assets are transacting off-market or within days of listing, and the buyers winning them are the ones who have their financing, structuring and advisers already in place.</p>', 'html', 'https://cdn.livfinder.com/magazine/where-the-world-s-wealthy-are-buying-in-2026-1.jpg', 'Where the World''s Wealthy Are Buying in 2026 — cover image', 8, 'draft', 'public', NULL, NULL, 1, 1, 1035281, 1, 'Where the World''s Wealthy Are Buying in 2026 | Liv Finder Magazine', 'Where the World''s Wealthy Are Buying in 2026. Analysis and guidance from the Liv Finder editorial team.', 0, 8, '2026-08-11 09:00:00');
