INSERT INTO faqs (question, answer, scope_type, language_id, sort_order, is_published) VALUES
('How do I list a property on Liv Finder?', 'Create an account, choose a plan that permits listings, and submit your first listing for review. Most listings are approved within a few hours.', 'global', 1, 1, 1),
('Are listings verified?', 'Every listing is reviewed before publication, and organisations must supply a valid trade licence and, in regulated markets, a brokerage registration.', 'global', 1, 2, 1),
('What does the verified badge mean?', 'It means both the lister and the specific listing have passed our checks, including licence validity and photograph provenance.', 'global', 1, 3, 1),
('How is my enquiry handled?', 'Your enquiry goes directly to the listing agent, who is expected to respond within our published service level. You will also see it in your portal.', 'global', 1, 4, 1),
('Can I search in my own currency?', 'Yes. Prices are stored in the listing''s own currency and converted for display using daily mid-market rates.', 'global', 1, 5, 1),
('Do you charge buyers?', 'No. Liv Finder is free for buyers. Listers pay a subscription.', 'global', 1, 6, 1),
('How do I remove a listing?', 'Withdraw it from your portal. It stops appearing immediately and the URL redirects rather than returning an error.', 'global', 1, 7, 1),
('What areas do you cover?', 'Every country, with full community and sub-community depth in the markets our sellers actually operate in. See our coverage documentation for detail.', 'global', 1, 8, 1);
